/** A setting row around a switch that really switches. */
function SwitchSetting({
  label,
  description,
  initial,
}: {
  label: string
  description?: string
  initial: boolean
}): ReactNode {
  const [on, setOn] = useState(initial)
  return (
    <SettingRow labels={labels} label={label} {...(description ? { description } : {})}>
      {({ labelId, describedById }) => (
        <Switch
          label={label}
          aria-labelledby={labelId}
          aria-describedby={describedById}
          checked={on}
          onCheckedChange={setOn}
        />
      )}
    </SettingRow>
  )
}

/** A setting row around a text field of the shared width. */
function TextSetting({
  label,
  description,
  initial,
  mono = false,
}: {
  label: string
  description?: string
  initial: string
  mono?: boolean
}): ReactNode {
  const [value, setValue] = useState(initial)
  return (
    <SettingRow labels={labels} label={label} {...(description ? { description } : {})}>
      {({ labelId, describedById }) => (
        <Wide>
          <span className={mono ? 'font-mono *:w-full' : '*:w-full'}>
            <Input
              label={label}
              aria-labelledby={labelId}
              aria-describedby={describedById}
              size="sm"
              value={value}
              onChange={(event) => setValue(event.target.value)}
            />
          </span>
        </Wide>
      )}
    </SettingRow>
  )
}

